  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (488::BIGINT, 'Mae llegué con hasta el primer parcial, luego la cátedra cambio el profesor, la verdad exelente profe explica muy bien y hace bastantes ejercicios en clases, los quiz son nivel de examen, pero si no práctica se le va a olvidar los temas entonces cuidado con eso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-09-30T00:00:00+00:00'::TIMESTAMPTZ, 'af573e70dff4bbee625f416ee95743d6a133ad659270a0e65627e0f9b317188c'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'f9143ec68293258d30d9c4f562b01397655af0d50e139498482e5946bb8844e9'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Excelente en todos los aspectos. Brinda material antes de cada clase para que veamos lo que se va a ver y es muy claro con sus explicaciones. Hace muchos quices durante el semestre pero lo ayuda a uno para ir preparado al examen. El mejor profe de CAL sin duda alguna.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '084de22a5583d19d9171ce9477cca05fb61d3d6cb23a7625de95d9c8bea2e175'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Súper buen profe, siempre envía el material que se verá en la clase de la semana antes de que empiece la misma y hasta lo hace pensando en los que apuntan en tablets. Súper claro con las explicaciones y hace quizzes semanales que garantizan que uno va bien y al día con la materia.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2026-06-22T00:00:00+00:00'::TIMESTAMPTZ, '35129072676859e24b35af1a4fd084ea962f995c2b48e15801e5231bf70ab18e'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Ayuda en horas de consulta y comparte material de práctica para los exámenes, también es ordenado con las evaluaciones. Califica justo los exámenes y no regala puntos . Es una opinión personal, pero el profe habla muy monótono, me costaba un poco prestarle atención en clase, aparte de eso, all good.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-01-07T00:00:00+00:00'::TIMESTAMPTZ, '181e17e3bdf4380bb795606793baa42cef58e032c0b0f7c9b47c3a41300149ba'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Le gusta que los estudiantes lleven la materia al día, por eso trata de hacer quices casi todas las semanas. Si usted se cree capaz de estudiar todas las semanas y no el día antes del examen, este profe es bastante recomendado, pero sepa que si no lo es la nota de los quices baja la global'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes']::TEXT[], '2025-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'c500cea6617f3a40699917f8abd9291ee13092a7a8b01370bd915014da863528'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Las clases son excelentes porque explica súper bien. Siempre brinda apoyo tanto dentro como fuera de las consultas. Pero casi siempre hay quices semanales y suelen ser bastante duros, eso si, lo preparan a uno muy bien para los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '475721b3250fde0c031a994c7c94cf15685be1b713a9ac8848fb234f9add4c7f'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Es un excelente profesor, creo que en general es muy ordenado en comparación a otros profes. Explica súper súper bien. Es súper amable en consulta. Eso si, deja quiz casi que todas la semanas y son bastante duros (y si es coordinador, los exámenes también). Súper recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-10-13T00:00:00+00:00'::TIMESTAMPTZ, '91842e732ae47110bbcfb92a319f90d4b96ac2cd41564b68590a743a8f87667b'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Es el mejor profe jurado, explica muy bien y hace apuntes digitales. Le atiende bien a uno en consulta. Hace quices cada 1 o 2 semanas, eso si, haga todo el lapicero SIEMPRE. Llevaria de nuevo con el definitivo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-30T00:00:00+00:00'::TIMESTAMPTZ, 'c7402ead3ce8b3eb25fa9debf4d616d1806b49ed1085f073d9cb0ffcd3e70408'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Buen profe, hace quizzes y tareas acorde a lo que explica. Da apuntes en digital lo que es útil para repasar. NUNCA le entregue trabajos o exámenes en lápiz. suele dar las notas en las últimas semanas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2025-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'ed29a2d50127af48b47409b698f9c853f5ab57dfa8a29577c94c6805c9988453'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'El profe es muy pura vida, solo que califica muy duro, tarda mucho en evaluar los quices y es un profe que no le agrada mucho dar la hora de consulta, asi que si es una persona que entiende con solo ir a clases dale, hace muchos quices y los evalua muy duro, pero en explicación es el mejor.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Clases excelentes']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'd63c18eed25f51489df603e556049af45e00571b89e5b4c441055c6aeccf5f0d'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'El profesor explica todos los temas con mucha claridad y resuelve muchos ejercicios en clase. Asigna bastantes tareas y quices pero son sencillos y útiles para comprender. Siempre hace ejercicios muy similares a los del examen y se devuelve a explicar las veces necesarias.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-07T00:00:00+00:00'::TIMESTAMPTZ, '0677e4c66d082d1fdebecb9df2ed7a08b85dd93ac8f2d8c6251c74b4a261aafe'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Explica super bien y es una persona muy amable y no va a dudar en ayudarlo si lo necesita. Califica bastante duro y los quiz son difíciles, dura bastante entregando evaluaciones y es un poco desordenado. Pero enseña muy bien y te prepara bien para los exámenes . Matricule con él si puede.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2025-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'ffa2b149e6e68250064a845d9703bc6e966bf913a2e41ea451f01bdba5f0a371'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-30T00:00:00+00:00'::TIMESTAMPTZ, '265156d832499b6cdddd0998b8663840ad00f19b0035a69607503c513a3fa022'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Top profe la verdad, se puede decir que califica duro, pero realmente califica acorde a como enseña. Las clases son excelentes, clarísimas, siempre pasa los apuntes de clase y comparte exámenes para practicar. Lo único que diría es que tarda bastante entregando las calificaciones de las evaluaciones'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'b7f6bbae2206e2a3b97582e830f75d3a7fc0f3cf181ed1b6d98324fa192cedea'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Demasiado desordenado. Explica bien y atiende dudas pero hasta ahí. Si puede matricule con cualquier otro profe.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, '188d0ba634643c7fbb1bd52e49db53a01ec73760fad8f0762aca7851b4b81391'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Explica bastante claro y atiende cualquier duda, deja material para repaso antes de los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'e8da11297fd6cbdba995ed124f89e068904636aec01ce74a08e84e177b75ea7f'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Excelente como persona y profesor, explica excelente y no hace ver ninguna pregunta como tonta. Explica de la manera mas sencilla. Califica muy suave comparado con otros. Eso sí, los quizes son duros, no da % extra el cual es muy necesario en el curso. Los ejemplos son muy fáciles respecto al examen'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, '4e7fefcd9fe4c498dc6c8c0749941431ec2d4b28d498565273b3541c3796c566'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'La verdad es un profe muy tuanis, nunca le va a faltar el respeto y siempre lo va a ayudar en lo que necesite. Si estudia para los quices a conciencia los pasa si o si, de igual manera con los examenes. Deja las clases resueltas en el telegram y en general muy ordenado'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2024-09-11T00:00:00+00:00'::TIMESTAMPTZ, 'fd04fc8145755c9856ae8950eb03ea45d2d5a8d6936df0b2ec6342eb8e0fc316'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'No pienso que sus quices sean díficiles o que calique duro. De hecho si usted pone atención en clase y practica lo necesesario; se pasa sencillo. Explica suuper claro, es respetuoso y muy amable incluso si usted tiene dudas "tontas". Para mi 10/10'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-07-23T00:00:00+00:00'::TIMESTAMPTZ, '9f2f9bca1a90d83676f4e3f5e0cfbdfaa7b87b872d2a5bc694dbe879095f8482'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'muy buen profe califica decente pero hace los quices de 2 preguntas y dificiles pero si le pone ganas se pasa con examenes'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '172d68e2cf711df984109ca6ab694f8316fa1350684ed3ba50f372b109d867e7'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'El profe explica bien pero realiza ejercicios muy básicos, tiene que dedicarle mucho tiempo por fuera, califica procedimiento pero no suave, los quices son solo 2 preguntas pero tienen cierto nivel de dificultad, deja prácticas largassssssss. Si lo lleva como él practique con la práctica semanal.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'f7d7bb9e7ab62e0eeab77fb23ae74c5afb7c73d544e381287c7f76bba533504f'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Empieza dando las clases super bien y terminamal. Es super serio y normalmente va volado. Realmente explica todo, pero los quizzes los hace para matar, realmente califica y evalua muy muy muy duro.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'e65df4983a17f0df84936e0181e845b5527f954278761b928e21f7cc4128d430'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Realmente es muy bueno explicando, lo que se ve en clase queda todo en archivos entonces es un plus porque puedes revisar apuntes. Califica duro los exámenes, hay que ser muy cuidadosos, los quizzes tienen una dificultad media-alta. Esto en verano.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2024-01-17T00:00:00+00:00'::TIMESTAMPTZ, '190f9a2ea5858290111cad802fa77eb2c0417f2884819aa92e06d22ed8f3c149'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Un profe muy bueno, va al punto, no pierde el tiempo, parece que tiene la clase a la medida'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'e946d4254b282ec4c364a83e0cad66a6b7a30635ee6ffd10da0b2e003255aab2'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, '70% examenes, 25% quizes & 5% khan academy. Los quizes eran muy difíciles comparado a lo que se ve en clase, el 5% del khan academy eran muchos ejercicios para lo que valia. El profesor ayuda mucho si uno va a consulta, pero para pasar hay que estudiar TODOS los días, al calificar no perdona nada.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2023-12-08T00:00:00+00:00'::TIMESTAMPTZ, '3d17460d17e8b21cd851321226f3cfe17fc23ba3eeebfd47360085b2b43ee2c6'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'El profe en sí es bueno explicando, pero los quices son muy difíciles además de que dejó muchos, también en Khan Academy y en las últimas semanas de clase. Si quiere pasar, tiene que practicar muchísimo (como toda mate) porque los ejercicios en clase son muy generales, da buena ayuda si pregunta.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2023-12-07T00:00:00+00:00'::TIMESTAMPTZ, '07a97be7fd90dcafc387699c30113034ece983c8a3ff92d35c588cce57857fff'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Fue el coordinador catedrático. Sus exámenes eran bastante confusos y complicados, nada comparados a los que se hicieron en semestres anteriores, además eran demasiado largos y tediosos. Califica rudísimo y no perdona absolutamente nada. No lo recomendaría.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2023-12-02T00:00:00+00:00'::TIMESTAMPTZ, '7cc154065a14ac2ac82fc093dd53f8a712fe7494e09bd947290d2ec15b425996'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'A ver, a mi me gusto y le entendía con facilidad al profesor, el profesor es muy buena gente, super respetuoso, y como persona es excelente. Los quices son duros pero lo preparan bien para el examen, lastimosamente para el periodo 2S 2023, los dos últimos exámenes fueron MUY distintos. Pasa material'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'c2f9bc6dc27241761fca8df28de793fca87fe93f13dc728f00b41babe99e9cc5'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'No llevé el curso con él, pero fue el coordinador de cátedra. Hacer todos los exámenes anteriores de práctica no sirvió de nada, porque dificultó demasiado el curso. Ejercicios innecesariamente difíciles y con trampas que al fin y al cabo no evaluaban si aprendió contenidos del curso. En desacuerdo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '0d52b235709a40c384c73d20b44403efbc821b9b800505361d468d0914fec57a'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Fue coordinador de CDI en 2S 2023.Hizo los exámenes mucho más difíciles que el semestre pasado, con ejercicios distintos y confusos.De nada vale desmotivar a estudiantes en un curso tan importante como CDI con exámenes tan difíciles (al compararlo con otros).Evitaría llevar curso con él.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, '55980c164417a496aa42ddd1f4b8dbb6ed7d2e55d4e57f34ec7ec7b78a1f131a'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'La gente dice que es un excelente profesor, pero tan bueno no lo considero, si bien explica bien, califica durísimo y los quices son muy heavy (sobre todo los que hace en el GAAP) , yo sinceramente no llevaría otro curso con el .'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2023-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'de49f77719125ad3cf0625392306881c41264ae393ca64e2106f5ebdcf74e5ac'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '6283465c4655a7b3a3cae97bb0b34c92fe0e876d0656fbc58ea252168e42696e'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'El profe explica muy bien, es muy atento con los estudiantes y aclara todas las dudas con gusto. Eso si, hay que ponerle bastante porque el profe no regala ni un sólo punto y califica medio duro. Hace quices todas las semanas y asistir a clases y repasar la cátedra es demasiado importante.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '101b20c3d8c1fceaafdcc6e1b1a722d6ca7ec3b872dfcd6494d12658a899e04c'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Excelente profe, matricule sin miedo. Da apuntes antes de cada clase, resuelve ejercicios de exámenes en clase, es atento y comprensivo con los estudiantes y explica las veces que sea necesarias para que todos entiendan.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'ef057c63457964cc9395b6da93164407b3af7ce1ad219e885db8c8c058a9305a'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-01-26T00:00:00+00:00'::TIMESTAMPTZ, '84ff1532ffe8b183f1246fa0b538be9f24052084c8c68552a91f7af62cc49fb7'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Es muy bueno. Explica muy claro y si tiene que aclararle algo de un curso anterior lo hace sin problema y repite la explicación las veces que sea necesario. Se nota que le gusta su profesión. Super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'ed9db3e08c76e75cbe717db348dc40e3b0654b3802451584ac503fb66a8b2a6e'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Excelente a la hora de explicar la materia. Repasa conceptos de materias anteriores rapidamente ya que es posible que uno no se acuerde muy bien de esos conceptos. Hace muchos ejercicios que le sirven a uno para los examenes. Quices son mas dificiles que los examenes, pero son de gran ayuda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, '795ffdb12962a703f2546325c8aadcabf8b8b61ba7c45096ad03f2dbd01bc684'::TEXT, ARRAY[935]::BIGINT[]),
    (488::BIGINT, 'El profesor es excelente, explica muy bien, es flexible y accesible. Intenta ayudar en lo que puede y explica las veces que sean necesarias. Los quices son un poco díficiles.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, '7608f4c65e06d382aa9763cc8631e34dbfb798a081afaa5d4885b27b87e2ae41'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Virtual, el profe es muy bueno, las clases son largas, explica bien, ayuda en todas las dudas que tengan.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'dc3223688751a50dc993161c6b442aa10dcef6549d948cdbf8597e2a230013ec'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Para ecua es buen profe, pero si usted es como yo y le gusta escribir toda la materia, se le va a imposibilitar, porque el profe usa muchas imágenes con texto y no le da tiempo a copiarlo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, '2e34e0e34ed7429592a7734c7dae5d11d03bf1cc16110e3cb98c4f05b0a71510'::TEXT, ARRAY[935]::BIGINT[]),
    (488::BIGINT, 'Buenísimo. Explica todo en clases y da muchísimos ejemplos que sirven para el examen. Explica súper claro y a buen ritmo. Hace quices todas las semanas entonces tiene que ir al día con la materia.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b88a7051b5a17ee6cad6df19a5ff480fdac3f9322f818f14abe4c7b30557dfb6'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Da muchos ejemplos durante la clase. En la clase virtual lo hizo todo a mano y es súper ordenado. Califica los trabajos rápidamente y casi todo lo hace a través del tec digital. Lo recomiendo totalmente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '702be3c70e653098c74e5f39f24c2966b0cf866ebd910132c14984a490748ed1'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '7c474842492e07403b0cd1755452f543d816565894813742fc48c350ce779a85'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Es buen profe de Mate, explica claro y al punto. Hace quices semanales, pero al final de semestre se hace un colocho revisando las varas'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '90d84afd12e4d894b622bfe6edbf7487ff7e5bac43fe076b7a8ed8adeb69b3d7'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Es un muy buen profe, pero explica con ejercicios muy sencillos, por lo que si quiere entender bien la materia tiene que practicar sí o sí.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'b1e3514438a86d76d02ea73843e6875dbbefe7143d4bbd17d984b22ef6077ac0'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'El profe es bastante bueno, solo que la cátedra cambió muchos ítems en las evaluaciones y el profe explica ejercicios diferentes a los que se evalúan, pero nadamás de hacer las prácticas recomendadas y listo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '21d6c33b477e974581e62186e9c95d08b76815e7d0b15994c58a4d271ee9d631'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'El curso virtual es bastante accesible. Semanalmente hace quices o tareas del último tema visto. Explica muy claro, se entiende bastante. De los mejores profes de la cátedra'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '631f9f356edba40050b79971dcd71a32db7eb6f2c0d74aa0724219df7e46cddc'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'El profe explica super bien las clases, muy ordenado, y muy atento si uno tiene alguna duda. llevaría otro curso con el definitivamente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-20T00:00:00+00:00'::TIMESTAMPTZ, '62072a9b12568a05932d3a02d2987d6c1f82940988f7c33f45d38b097c17a126'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '3fd3a6ef5c00fae4435118c967a30d04504831a2b7d7f9ae681afc01228e26fa'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'f8debfe075de5c4c33f364fb659d559bcff886619e7f2e4cf43cdb2cb9620e91'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Excelente explicando. Se adaptó super bien a los métodos virtuales, graba y sube todas las lecciones. Explica muchos ejemplos de cada tema hasta que todo quede claro. 100/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '744d3b10b6b7538655815fe923e0dd8cf3d4ee3fc06372e20ba683da06a93591'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'El mae explica muy bien si, solo que hace quizes muy duros, pero a la vez prepara bien para el examen'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '8cd1bd894cc67cd6c1060bfc229510523b743d9a3ad888a2139812fb24961d05'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Muy buen profe, explica todas las veces que sea necesario, hace bastante practica en clases para explicar, lo unico en lo que fallo es respondiendo consultas especificas, algunas las respondia rapido y otras no las respondia del todo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '40bc3078c569a3caf29777aa210c4f48527d843b2af1f1d11c96178b7fcf443b'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Mae, súper bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'e4d1c11e74f38d42589eef4e8ef9fc7d4b86b3f8daf205b8068ec9d043b818a9'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Excelentes explicaciones, demasiado atento con los estudiantes, quices duros semanales.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '4bf89b64a6bb62cfe0c0b45e6b46d60802f5ac7652715f2904c0f3e998bb7e3d'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Es una excelente profesor, ayuda mucho, si ocupas que te explique 1000 veces lo hace, es muy claro al hablar, si deja tarea son como los ejercicios que explica, lleve el curso con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '3b0cac43a10202584dc2606a40e2d21724dcecf4dfa41ef8ac1e278929f1c64b'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '1cdcfbfdf56d1e0bcb7af7fbe784f63993508ccb4ce79ec471d897e5b6d3a080'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'En general muy buen profesor, es muy claro al explicar y no le molesta volver a dar la explicación en caso de que no haya entendido. Las calificaciones van muy de la mano con la materia vista y si se va al día de fijo se pasa.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-06-30T00:00:00+00:00'::TIMESTAMPTZ, '3946c00fcd551140e9c362af58e46383b0871a26a8c4501284fa6d26d2308f3f'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'muy buen profesor,pero los exámenes los hizo demasiado complicados. como profe llevaría de nuevo con el es muy bueno, pero en verano nunca mas porque se pasa en los exámenes'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-19T00:00:00+00:00'::TIMESTAMPTZ, '7b520545dec7f58f1ed628bd0f311a4798ae0d18c628ce1e375b0dc6e0ce553d'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Explica muy claro, da ejercicios recomendados similares a los del examen. Excelente profesor, los exámenes los entrega rápido, solo las evaluaciones en línea y tareas dura un poco más entregándolas. Es uno de los mejores profesores para álgebra y en general para cualquier curso de matemática.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'ff2ccd95b5e544ba6fd3e12ea041b37a744ac2fdaa980bc73601bbd9912a9e1c'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-19T00:00:00+00:00'::TIMESTAMPTZ, '244743309060ac14101a9e8c30fed3aa3d7bfec5cbe8ffd33669d0544ce7f24f'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Apenas llevo 4 clases y ya puedo decir que es un crack , súper recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-13T00:00:00+00:00'::TIMESTAMPTZ, '047b39eff972a6b4af64404c82073417df258d73c10c14a1f27ebeab71c359bf'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Excelente profe, es importante ir y poner atención ya que explica super bien, ayuda si el ve interés en usted, las horas de consulta son muy buenas. Y no califica mal.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, '8685b93b80bf90d53490fa20f7ebe4a037814e77484ba1a9250bc51a2f4c98de'::TEXT, ARRAY[634]::BIGINT[]),
