    (488::BIGINT, 'Es un excelente profesor. Explica muy bien y se preocupa porque el estudiante aprenda de verdad, realmente él no está solo por dar la clase y nada más. A veces hace quizes difíciles pero prepara bien para los exámenes. De los mejores profes de matemáticas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '951b2004bfde9db144c8cdb3b4dcdde36b70e44eaee0f2ab903e11e5f57071d2'::TEXT, ARRAY[1041]::BIGINT[]),
