    (488::BIGINT, 'Explica demasiado bien, es muy buena nota. Hace quices medio duros a veces pero vale la pena un curso con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'e906e9088557ac19b815d2de3ee9b8c08c82f1a87895bb225c1f444c66390b78'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Este profe explica como si fueramos chiquitos de kinder, lo cual es perfecto porque explica con muchisisisimo detalle! recomendadísimo! :)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '9e60ecfb1ca1ae31a387b087da0e824abaedf089561037acbb9c97b9f84815a2'::TEXT, ARRAY[1041, 1034]::BIGINT[]),
    (488::BIGINT, 'Excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'efaea21ee8c86f57ffbf029fa2f874dccf920fb0dc60df62f112fb1cf2738305'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Sin duda de los mejores, explica demasiado bien y hace quices a menudo, no hay ni que estudiar para los exámenes porque se llega muy preparado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'b69db9eaa96817ddb5c0dbe8b5fe7990339f4bc9f986d67d1589e41198f4d183'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Probablemente el mejor Profe de mate en esa escuela, se nota que disfruta ser Profe, es excelente explicando, se preocupa por que uno le entienda y aprenda..'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f6613717fa46a280d0811f64858b84bf95575b5180610d66afc8026690a19021'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Explica excelente, lo negativo es que es muy intenso, utiliza todo el tiempo de la clase, por lo que se hace cansado, pero se aprende muchísimo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '86e2e7ffe1cb6657fb7e1278a4047c4f516d68406d30052a04aed194cf955e1a'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '5abeafc8825ae3c828942ea53fc4116009e12b4089773966862e8444b873fbf3'::TEXT, ARRAY[634]::BIGINT[]),
    (488::BIGINT, 'Sus clases no dejan dudas, son muy claras.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '3f9f9c33015e16920689ab714b304610addfd126cb38d1a9b35fb28f60a0b79d'::TEXT, ARRAY[1041]::BIGINT[]),
    (488::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'ee57b471b8191c3328c7941827ba19a8ce244b52e1627bc1c801e7241289cae4'::TEXT, ARRAY[605]::BIGINT[]),
    (488::BIGINT, 'Es muy buen profesor y se preocupa porque los alumnos aprendan bastante'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '8284c6c14469befb6bcecafc0fcc6d28a64a2bbd9209dc5937ddc9f8b89ebfdf'::TEXT, ARRAY[563, 2439]::BIGINT[]),
    (488::BIGINT, 'Califica a como explica. Muy buen profesor.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'a9817a24f32c07be2a06240c7f809cf6d444aede98693066ac47cdea54a4539e'::TEXT, ARRAY[563]::BIGINT[]),
    (488::BIGINT, 'Es un profe muy completo, sabe explicar muy bien y en caso que uno no sepa algo el atiende de manera muy paciente. La forma de calificar es muy buena.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'fcc1e7125d1940063060bb8df04bd7a904168f63b6b73f829de0d97f0344c40a'::TEXT, ARRAY[563]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
